  authorId = BOB,
  assigneeId: typeof ALICE | typeof BOB | null = null,
): PermissionResource {
  return {
    kind: "issue",
    orgId: ORG_A,
    projectId: PROJECT,
    issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
    authorId,
    assigneeId,
  };
}

PROJECT,
    issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
